        for length in range(lo, hi + 1):
            for t0 in range(0, n_periods - length + 1):
                yield t0, length

    def _mask_from_positions(self, positions):
        mask = 0
        for p in positions:
            mask |= 1 << p
        return mask

    def moves(self, sol):
        inst = self.problem.inst
        n_items, n_periods = inst.n_items, inst.n_periods

        items = []
        for i in range(n_items):
            count = sum(1 for t in range(n_periods) if sol[i][t])
            if count >= 1:
                items.append((count, i))

        if not items:
            return

        items.sort(key=lambda x: (x[0], x[1]))
        items = [i for _, i in items[: max(1, min(self.max_items, len(items)))]]

        yielded = 0
        for i in items:
            row = sol[i]
            for t0, length in self._windows(n_periods):
                active = [p for p in range(length) if row[t0 + p]]
                if not active:
                    continue

