                # luego bloques de tamaño 2, y después subconjuntos más grandes.
                masks = []
                seen = set()

                for r in range(1, min(len(active), length) + 1):
                    for combo in combinations(active, r):
                        mask = self._mask_from_positions(combo)
                        if mask in seen:
                            continue
                        seen.add(mask)
                        masks.append(mask)

                masks.sort(key=lambda m: (m.bit_count(), m))
                for mask in masks[: self.max_masks_per_window]:
                    yield (i, t0, length, mask)
                    yielded += 1
                    if yielded >= 10000:
                        return

    def apply(self, sol, m):
        i, t0, length, mask = m
        s = [list(row) for row in sol]
        for p in range(length):
            if (mask >> p) & 1:
                s[i][t0 + p] = False
        return tuple(tuple(row) for row in s)

    def undo(self, sol, m):
        i, t0, length, mask = m
        s = [list(row) for row in sol]
        for p in range(length):
            if (mask >> p) & 1:
                s[i][t0 + p] = True
        return tuple(tuple(row) for row in s)

    def delta(self, sol, m):
        return self.problem.objective(self.apply(sol, m)) - self.problem.objective(sol)


